-- LSN-1.3.5: Unit 1 레슨 2개(u1-l1, lesson2) content 를 파이프라인 결과로 통째 교체 (멱등).
-- 생성: backend/admin-tools/kiwi-generator/batch_merger.py --base-json backend/lessons/unit1/<파일> + curriculum.csv
-- 조립 문제: u1-l1 = 은/는(JX) 만 분해, lesson2 = 이에요/예요(VCP) 만 분해('저는' 통째), 구두점 블록 없음, 선택지 id, 영어 설명
-- 탭 분석 chunks: 기호 토큰 제거, 이름/화자 표시, '이예요' 제거. u1-l1 Pattern Practice 에 '은' 문항 추가.
-- lsn_002 이후에 적용 (lesson2 completion 은 lsn_002 와 같은 내용 포함).
BEGIN;
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "intro", "title": "Today's Goal", "instruction": "Let's learn how to introduce yourself and the major Korean particle '는'.", "content": {"explanation": {"title": "I am... (Introducing Yourself)"}, "sentences": [{"korean": "안녕하세요! 제 이름은 Sarah예요.", "english": "Hello! My name is Sarah.", "tts": true, "chunks": [{"display": "안녕하세요!", "tokens": [{"text": "안녕하세요", "meaning": "Hello"}]}, {"display": "제", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "의", "meaning": "possessive marker"}]}, {"display": "이름은", "tokens": [{"text": "이름", "meaning": "name"}, {"text": "은", "meaning": "topic marker"}]}, {"display": "Sarah예요.", "tokens": [{"text": "Sarah", "meaning": "Sarah (name)"}, {"text": "예요", "meaning": "am/is/are (polite)"}]}]}]}}, {"step_type": "intro", "title": "Conversation #1", "instruction": "Listen to the introduction between Sarah and Minsu.", "content": {"explanation": {"title": "Meeting for the first time"}, "sentences": [{"korean": "민수: 안녕하세요?", "english": "Minsu: Hello?", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "안녕하세요?", "tokens": [{"text": "안녕하세요", "meaning": "Hello"}]}]}, {"korean": "Sarah: 안녕하세요. 저는 Sarah입니다.", "english": "Sarah: Hello. I am Sarah.", "tts": true, "chunks": [{"display": "Sarah:", "tokens": [{"text": "Sarah", "meaning": "Sarah (speaker)"}]}, {"display": "안녕하세요.", "tokens": [{"text": "안녕하세요", "meaning": "Hello"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "Sarah입니다.", "tokens": [{"text": "Sarah", "meaning": "Sarah (name)"}, {"text": "입니다", "meaning": "am/is/are (formal)"}]}]}, {"korean": "민수: 반갑습니다. 저는 민수입니다.", "english": "Minsu: Nice to meet you. I am Minsu.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "반갑습니다.", "tokens": [{"text": "반갑습니다", "meaning": "Nice to meet you"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "민수입니다.", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}, {"text": "입니다", "meaning": "am/is/are (formal)"}]}]}]}}, {"step_type": "intro", "title": "Conversation #2", "instruction": "Another example with different names.", "content": {"explanation": {"title": "Tom and Yumi meeting"}, "sentences": [{"korean": "Tom: 안녕하세요. 저는 Tom입니다.", "english": "Tom: Hello. I am Tom.", "tts": true, "chunks": [{"display": "Tom:", "tokens": [{"text": "Tom", "meaning": "Tom (speaker)"}]}, {"display": "안녕하세요.", "tokens": [{"text": "안녕하세요", "meaning": "Hello"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "Tom입니다.", "tokens": [{"text": "Tom", "meaning": "Tom (name)"}, {"text": "입니다", "meaning": "am/is/are (formal)"}]}]}, {"korean": "유미: 반갑습니다. 제 이름은 유미예요.", "english": "Yumi: Nice to meet you. My name is Yumi.", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "반갑습니다.", "tokens": [{"text": "반갑습니다", "meaning": "Nice to meet you"}]}, {"display": "제", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "의", "meaning": "possessive marker"}]}, {"display": "이름은", "tokens": [{"text": "이름", "meaning": "name"}, {"text": "은", "meaning": "topic marker"}]}, {"display": "유미예요.", "tokens": [{"text": "유미", "meaning": "Yumi (name)"}, {"text": "예요", "meaning": "am/is/are (polite)"}]}]}]}}, {"step_type": "intro", "title": "Grammar: Topic Particle 은/는", "instruction": "The most important concept in Korean grammar.", "content": {"explanation": {"title": "What is 는?", "patterns": [{"pattern": "는 / 은", "level": "Essential", "usage": "It marks the topic of the sentence."}]}, "sentences": [{"korean": "저는 = I (topic)", "english": "저 (I) + 는 (Topic Particle)", "tts": false, "chunks": [{"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "=", "tokens": []}, {"display": "I", "tokens": []}, {"display": "(topic)", "tokens": []}]}, {"korean": "민수는 = Minsu (topic)", "english": "민수 (Minsu) + 는 (Topic Particle)", "tts": false, "chunks": [{"display": "민수는", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "=", "tokens": []}, {"display": "Minsu", "tokens": []}, {"display": "(topic)", "tokens": []}]}]}}, {"step_type": "practice", "title": "Pattern Practice", "instruction": "See how it works with different names.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I am Tom.", "sentence": "저 [ ? ] Tom입니다.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Correct! 저 + 는"}}, {"type": "fill_blank", "instruction": "Minsu is a student.", "sentence": "민수 [ ? ] 학생입니다.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Great! 민수 + 는"}}, {"type": "fill_blank", "instruction": "Emma is a teacher.", "sentence": "Emma [ ? ] 선생님입니다.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Perfect! Emma + 는"}}, {"type": "fill_blank", "sentence": "제 이름 [ ? ] Tom입니다.", "options": ["은", "는"], "answer": "은", "instruction": "My name is Tom.", "feedback": {"correct": "Right! 이름 ends in a consonant (ㅁ), so it takes 은."}}]}}, {"step_type": "practice", "title": "Make Your Own", "instruction": "Now it's your turn! Type your name.", "content": {"exercises": [{"type": "user_input", "instruction": "Complete the sentence with your name.", "template": "저는 {input}입니다.", "feedback": {"correct": "Great job! That's how you introduce yourself."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"I am Sarah.\"", "contentObj": {"sentence": "저는 Sarah입니다.", "translation": "I am Sarah.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저", "는"], "turtle_explanation": "'는' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["Sarah입니다"], "correct_turtle": ["Sarah입니다"], "turtle_explanation": "Keep 'Sarah입니다' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "은", "mode": "turtle"}, {"id": "o2", "text": "저은", "mode": "rabbit"}, {"id": "o3", "text": "저", "mode": "turtle"}, {"id": "o4", "text": "Sarah입니다", "mode": "rabbit"}, {"id": "o5", "text": "는", "mode": "turtle"}, {"id": "o6", "text": "저는", "mode": "rabbit"}, {"id": "o7", "text": "도", "mode": "turtle"}, {"id": "o8", "text": "Sarah입니다", "mode": "turtle"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"My name is Yumi.\"", "contentObj": {"sentence": "제 이름은 유미예요.", "translation": "My name is Yumi.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["제"], "correct_turtle": ["제"], "turtle_explanation": "Keep '제' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["이름은"], "correct_turtle": ["이름", "은"], "turtle_explanation": "'은' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["유미예요"], "correct_turtle": ["유미예요"], "turtle_explanation": "Keep '유미예요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "유미예요", "mode": "turtle"}, {"id": "o2", "text": "제", "mode": "rabbit"}, {"id": "o3", "text": "도", "mode": "turtle"}, {"id": "o4", "text": "이름", "mode": "turtle"}, {"id": "o5", "text": "유미예요", "mode": "rabbit"}, {"id": "o6", "text": "이름은", "mode": "rabbit"}, {"id": "o7", "text": "제", "mode": "turtle"}, {"id": "o8", "text": "은", "mode": "turtle"}, {"id": "o9", "text": "이름는", "mode": "rabbit"}, {"id": "o10", "text": "는", "mode": "turtle"}]}}, {"step_type": "completion", "title": "Lesson 1 Mastered!", "instruction": "Amazing! You can now introduce yourself in Korean.", "content": {"text": "You've learned '저는 [Name]입니다.'\nKeep practicing this pattern!", "highlights": ["은/는", "입니다"]}}]}$lsn$::jsonb
WHERE lesson_id = 'u1-l1';
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "intro", "title": "Today's Goal", "instruction": "Let's learn how to ask about someone's job and answer using 이에요/예요.", "content": {"explanation": {"title": "Asking about jobs"}, "sentences": [{"korean": "무슨 일 하세요?", "english": "What do you do? (lit: What work do you do?)", "tts": true, "chunks": [{"display": "무슨", "tokens": [{"text": "무슨", "meaning": "what"}]}, {"display": "일", "tokens": [{"text": "일", "meaning": "work/job"}]}, {"display": "하세요?", "tokens": [{"text": "하", "meaning": "do"}, {"text": "세요", "meaning": "polite ending"}]}]}]}}, {"step_type": "intro", "title": "Conversation #1", "instruction": "Listen to the conversation between Minsu and Yumi.", "content": {"explanation": {"title": "Talking about professions"}, "sentences": [{"korean": "민수: 유미 씨는 무슨 일 하세요?", "english": "Minsu: Yumi, what do you do?", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "유미", "tokens": [{"text": "유미", "meaning": "Yumi (name)"}]}, {"display": "씨는", "tokens": [{"text": "씨", "meaning": "Mr./Ms."}, {"text": "는", "meaning": "topic marker"}]}, {"display": "무슨", "tokens": [{"text": "무슨", "meaning": "what"}]}, {"display": "일", "tokens": [{"text": "일", "meaning": "work/job"}]}, {"display": "하세요?", "tokens": [{"text": "하", "meaning": "do"}, {"text": "세요", "meaning": "polite ending"}]}]}, {"korean": "유미: 저는 학생이에요.", "english": "Yumi: I am a student.", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "학생이에요.", "tokens": [{"text": "학생", "meaning": "student"}, {"text": "이에요", "meaning": "am/is/are (polite)"}]}]}, {"korean": "민수: 아, 저는 의사예요.", "english": "Minsu: Ah, I am a doctor.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "아,", "tokens": [{"text": "아", "meaning": "Ah"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "의사예요.", "tokens": [{"text": "의사", "meaning": "doctor"}, {"text": "예요", "meaning": "am/is/are (polite)"}]}]}]}}, {"step_type": "intro", "title": "Grammar: 이에요 / 예요", "instruction": "이에요 and 예요 mean 'am/is/are'. They are attached directly to the noun.", "content": {"explanation": {"title": "Consonant vs Vowel ending"}, "sentences": [{"korean": "학생이에요", "english": "학생 (ends with consonant ㅇ) + 이에요", "tts": false, "chunks": [{"display": "학생이에요", "tokens": [{"text": "학생", "meaning": "student"}, {"text": "이에요", "meaning": "am/is/are (polite)"}]}]}, {"korean": "의사예요", "english": "의사 (ends with vowel ㅏ) + 예요", "tts": false, "chunks": [{"display": "의사예요", "tokens": [{"text": "의사", "meaning": "doctor"}, {"text": "예요", "meaning": "am/is/are (polite)"}]}]}]}}, {"step_type": "practice", "title": "Practice", "instruction": "Choose the correct ending for the job.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I am a teacher.", "sentence": "저는 선생님 [ ? ].", "options": ["이에요", "예요"], "answer": "이에요", "feedback": {"correct": "Correct! '선생님' ends with a consonant, so it takes '이에요'."}}, {"type": "fill_blank", "instruction": "I am a doctor.", "sentence": "저는 의사 [ ? ].", "options": ["이에요", "예요"], "answer": "예요", "feedback": {"correct": "Great! '의사' ends with a vowel, so it takes '예요'."}}]}}, {"step_type": "intro", "title": "Vocabulary: Jobs", "instruction": "Let's learn some common jobs in Korean.", "content": {"explanation": {"title": "Common Jobs"}, "sentences": [{"korean": "학생", "english": "Student", "tts": true, "chunks": [{"display": "학생", "tokens": [{"text": "학생", "meaning": "student"}]}]}, {"korean": "선생님", "english": "Teacher", "tts": true, "chunks": [{"display": "선생님", "tokens": [{"text": "선생님", "meaning": "teacher"}]}]}, {"korean": "의사", "english": "Doctor", "tts": true, "chunks": [{"display": "의사", "tokens": [{"text": "의사", "meaning": "doctor"}]}]}, {"korean": "회사원", "english": "Office Worker", "tts": true, "chunks": [{"display": "회사원", "tokens": [{"text": "회사원", "meaning": "office worker"}]}]}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"I am a student.\"", "contentObj": {"sentence": "저는 학생이에요.", "translation": "I am a student.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저는"], "turtle_explanation": "Keep '저는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["학생이에요"], "correct_turtle": ["학생", "이에요"], "turtle_explanation": "'이에요' means 'am/is/are'. After a consonant use 이에요, after a vowel use 예요."}], "options": [{"id": "o1", "text": "예요", "mode": "turtle"}, {"id": "o2", "text": "입니다", "mode": "turtle"}, {"id": "o3", "text": "이에요", "mode": "turtle"}, {"id": "o4", "text": "학생이에요", "mode": "rabbit"}, {"id": "o5", "text": "저는", "mode": "turtle"}, {"id": "o6", "text": "학생", "mode": "turtle"}, {"id": "o7", "text": "저는", "mode": "rabbit"}, {"id": "o8", "text": "학생예요", "mode": "rabbit"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"I am a doctor.\"", "contentObj": {"sentence": "저는 의사예요.", "translation": "I am a doctor.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저는"], "turtle_explanation": "Keep '저는' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["의사예요"], "correct_turtle": ["의사", "예요"], "turtle_explanation": "'예요' means 'am/is/are'. After a consonant use 이에요, after a vowel use 예요."}], "options": [{"id": "o1", "text": "의사이에요", "mode": "rabbit"}, {"id": "o2", "text": "의사", "mode": "turtle"}, {"id": "o3", "text": "입니다", "mode": "turtle"}, {"id": "o4", "text": "저는", "mode": "turtle"}, {"id": "o5", "text": "예요", "mode": "turtle"}, {"id": "o6", "text": "의사예요", "mode": "rabbit"}, {"id": "o7", "text": "저는", "mode": "rabbit"}, {"id": "o8", "text": "이에요", "mode": "turtle"}]}}, {"step_type": "completion", "title": "Great Job!", "instruction": "You have completed Lesson 2.", "content": {"text": "You've learned '저는 [job]이에요/예요.'\nConsonant ending → 이에요 (학생이에요), vowel ending → 예요 (의사예요).", "highlights": ["이에요", "예요"]}}]}$lsn$::jsonb
WHERE lesson_id = 'lesson2';
COMMIT;
